update cbs.t_promise
prod_sets = #{p.prod_sets}, stop_sets = #{p.stop_sets}, hazard_lv1 = #{p.hazard_lv1}, hazard_lv2 = #{p.hazard_lv2}, hazard_lv3 = #{p.hazard_lv3}, hazard_lv4 = #{p.hazard_lv4}, start_sets = #{p.start_sets}, stop_dev_sets = #{p.stop_dev_sets}, trial_sets = #{p.trial_sets}, supervision_process = #{p.supervision_process}, repair_sets = #{p.repair_sets}, fire_special = #{p.fire_special}, fire_lv1 = #{p.fire_lv1}, fire_lv2 = #{p.fire_lv2}, confined = #{p.confined}, blind = #{p.blind}, work_height = #{p.work_height}, lifting = #{p.lifting}, temp_power = #{p.temp_power}, digging = #{p.digging}, road_close = #{p.road_close}, repair_work = #{p.repair_work}, has_contractor_work = #{p.has_contractor_work}, in_trial = #{p.in_trial}, in_startstop = #{p.in_startstop}, in_pilot = #{p.in_pilot}, has_major_hazard = #{p.has_major_hazard}, company_promise = #{p.company_promise},
